// 3D farm viewer: loads /farm/farm.glb (generated by tools/farm/build_farm.py) and adds
// sky, sun shadows, image-based lighting, a splatted terrain shader, instanced grass and wind.
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { Sky } from 'three/addons/objects/Sky.js';
import { MeshoptDecoder } from 'three/addons/libs/meshopt_decoder.module.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { GTAOPass } from 'three/addons/postprocessing/GTAOPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';

const params = new URLSearchParams(location.search);
const QUALITY = params.get('quality') || (matchMedia('(pointer: coarse)').matches ? 'low' : 'high');
const HIGH = QUALITY === 'high';
const STILL = params.has('still'); // render a few frames then stop (thumbnails, screenshots)

// ---------------------------------------------------------------- renderer, scene, camera
const renderer = new THREE.WebGLRenderer({ antialias: !HIGH, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, HIGH ? 2 : 1.25));
renderer.setSize(innerWidth, innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 0.62;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.prepend(renderer.domElement);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, 0.3, 4000);
camera.position.set(46, 17, 46);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(2, 3, -8);
controls.enableDamping = true;
controls.maxPolarAngle = Math.PI / 2 - 0.03;
controls.minDistance = 4;
controls.maxDistance = 260;
controls.autoRotateSpeed = 0.35;
const vec = (str) => str && str.split(',').map(Number).length === 3 ? new THREE.Vector3(...str.split(',').map(Number)) : null;
if (vec(params.get('cam'))) camera.position.copy(vec(params.get('cam')));
if (vec(params.get('target'))) controls.target.copy(vec(params.get('target')));

// ---------------------------------------------------------------- sky, sun, environment light
const sky = new Sky();
sky.scale.setScalar(6000);
scene.add(sky);
const skyU = sky.material.uniforms;
skyU.turbidity.value = 3.2;
skyU.rayleigh.value = 1.1;
skyU.mieCoefficient.value = 0.004;
skyU.mieDirectionalG.value = 0.82;

const sun = new THREE.DirectionalLight(0xfff0dc, 4.4);
sun.castShadow = true;
sun.shadow.mapSize.setScalar(HIGH ? 4096 : 2048);
Object.assign(sun.shadow.camera, { left: -75, right: 75, top: 75, bottom: -75, near: 1, far: 420 });
sun.shadow.bias = -0.0004;
sun.shadow.normalBias = 0.05;
scene.add(sun, sun.target);

const pmrem = new THREE.PMREMGenerator(renderer);
const envScene = new THREE.Scene();
const envSky = new THREE.Mesh(sky.geometry, sky.material);
envSky.scale.setScalar(900);
envScene.add(envSky);
let envRT = null;

const SUN_AZIMUTH = 215; // degrees, same as the Blender scene
const sunDir = new THREE.Vector3();
function setSun(elevationDeg) {
  const phi = THREE.MathUtils.degToRad(90 - elevationDeg);
  const theta = THREE.MathUtils.degToRad(SUN_AZIMUTH);
  // Blender azimuth is measured from +Y (north) toward +X; three's north is -Z
  sunDir.set(Math.sin(theta) * Math.sin(phi), Math.cos(phi), -Math.cos(theta) * Math.sin(phi));
  skyU.sunPosition.value.copy(sunDir);
  const low = THREE.MathUtils.smoothstep(elevationDeg, 2, 25);
  sun.color.setRGB(1, 0.72 + 0.25 * low, 0.5 + 0.4 * low);
  sun.intensity = 0.8 + 3.6 * low;
  sun.position.copy(sunDir).multiplyScalar(200).add(sun.target.position);
  const fogCol = new THREE.Color().setRGB(0.70 + 0.1 * (1 - low), 0.76 - 0.02 * (1 - low), 0.82 - 0.12 * (1 - low));
  scene.fog.color.copy(fogCol);
  if (envRT) envRT.dispose();
  envRT = pmrem.fromScene(envScene, 0, 0.1, 5000);
  scene.environment = envRT.texture;
}
scene.fog = new THREE.FogExp2(0xbac8d4, 0.0026);
scene.environmentIntensity = 0.45;

// ---------------------------------------------------------------- post-processing
let composer = null;
if (HIGH) {
  const rt = new THREE.WebGLRenderTarget(innerWidth, innerHeight, { samples: 4, type: THREE.HalfFloatType });
  composer = new EffectComposer(renderer, rt);
  composer.setPixelRatio(Math.min(devicePixelRatio, 1.5));
  composer.addPass(new RenderPass(scene, camera));
  const gtao = new GTAOPass(scene, camera, innerWidth, innerHeight);
  gtao.updateGtaoMaterial({ radius: 0.6, distanceExponent: 1.5, thickness: 1.2, scale: 1.0 });
  gtao.blendIntensity = 0.85;
  composer.addPass(gtao);
  composer.addPass(new OutputPass());
}

// ---------------------------------------------------------------- shared wind uniform
const wind = { uTime: { value: 0 } };

/** Sway vertices by height above the mesh origin (metres). */
function addWind(material, amount, power = 2.0, keepNormals = false) {
  const prev = material.onBeforeCompile;
  material.onBeforeCompile = (sh, r) => {
    prev?.call(material, sh, r);
    sh.uniforms.uTime = wind.uTime;
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\nuniform float uTime;')
      .replace('#include <begin_vertex>', `#include <begin_vertex>
        #ifdef USE_INSTANCING
          vec3 swayOrigin = (modelMatrix * instanceMatrix[3]).xyz;
        #else
          vec3 swayOrigin = modelMatrix[3].xyz;
        #endif
        float swayH = max(position.y, 0.0);
        float swayA = ${amount.toFixed(4)} * pow(swayH, ${power.toFixed(2)});
        float swayP = uTime * 1.6 + swayOrigin.x * 0.21 + swayOrigin.z * 0.17;
        transformed.x += swayA * (sin(swayP) + 0.35 * sin(swayP * 2.7 + position.x * 2.0));
        transformed.z += swayA * 0.6 * cos(swayP * 0.8 + position.z * 1.7);`);
    if (keepNormals) {
      // foliage cards carry "crown" normals: don't flip them on back faces
      sh.fragmentShader = sh.fragmentShader.replace(
        'float faceDirection = gl_FrontFacing ? 1.0 : - 1.0;', 'float faceDirection = 1.0;');
    }
  };
  material.customProgramCacheKey = () => `wind${amount}${power}${keepNormals}`;
}

// ---------------------------------------------------------------- anti-tiling macro variation
// Multiplies albedo/roughness by low-frequency world-space noise so repeating textures on
// large surfaces (barn walls, roofs, silo) don't line up into visible patterns.
const NOISE_GLSL = `
  float mvHash(vec3 p) { p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
  float mvNoise(vec3 x) {
    vec3 i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f);
    return mix(mix(mix(mvHash(i), mvHash(i + vec3(1,0,0)), f.x), mix(mvHash(i + vec3(0,1,0)), mvHash(i + vec3(1,1,0)), f.x), f.y),
               mix(mix(mvHash(i + vec3(0,0,1)), mvHash(i + vec3(1,0,1)), f.x), mix(mvHash(i + vec3(0,1,1)), mvHash(i + vec3(1,1,1)), f.x), f.y), f.z);
  }`;

function addMacro(material, amount) {
  const prev = material.onBeforeCompile;
  material.onBeforeCompile = (sh, r) => {
    prev?.call(material, sh, r);
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\nvarying vec3 vMacroPos;')
      .replace('#include <project_vertex>', `#include <project_vertex>
        vec4 macroP = vec4(transformed, 1.0);
        #ifdef USE_INSTANCING
          macroP = instanceMatrix * macroP;
        #endif
        vMacroPos = (modelMatrix * macroP).xyz;`);
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', `#include <common>\nvarying vec3 vMacroPos;${NOISE_GLSL}`)
      .replace('#include <map_fragment>', `#include <map_fragment>
        float macroN = mvNoise(vMacroPos * 0.45) * 0.6 + mvNoise(vMacroPos * 1.7 + 7.3) * 0.4;
        diffuseColor.rgb *= mix(1.0 - ${amount.toFixed(3)}, 1.0 + ${(amount * 0.6).toFixed(3)}, macroN);`);
  };
  const prevKey = material.customProgramCacheKey?.bind(material);
  material.customProgramCacheKey = () => `${prevKey ? prevKey() : ''}macro${amount}`;
}

// ---------------------------------------------------------------- terrain splat material
function terrainMaterial(layers) {
  const g = layers.grass;
  const m = new THREE.MeshStandardMaterial({
    map: g.map, normalMap: g.normalMap, roughnessMap: g.roughnessMap, vertexColors: true, roughness: 1, metalness: 0,
  });
  m.normalScale.set(1, 1);
  m.onBeforeCompile = (sh) => {
    Object.assign(sh.uniforms, {
      dirtMap: { value: layers.dirt.map }, dirtNormal: { value: layers.dirt.normalMap }, dirtRough: { value: layers.dirt.roughnessMap },
      soilMap: { value: layers.soil.map }, soilNormal: { value: layers.soil.normalMap }, soilRough: { value: layers.soil.roughnessMap },
      soilScale: { value: 3.0 / 3.2 },
    });
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', `#include <common>
        uniform sampler2D dirtMap, dirtNormal, dirtRough, soilMap, soilNormal, soilRough;
        uniform float soilScale;`)
      .replace('#include <color_fragment>', '')
      .replace('#include <map_fragment>', `
        vec2 uvS = vMapUv * soilScale;
        float breakup = texture2D(map, vMapUv * 0.37 + 0.13).g;
        float macro = texture2D(map, vMapUv * 0.061).g + texture2D(dirtMap, vMapUv * 0.023).r;
        float wD = smoothstep(0.38, 0.62, vColor.r + (breakup - 0.25) * 0.9);
        float wS = smoothstep(0.30, 0.55, vColor.g + (breakup - 0.25) * 0.4);
        vec3 cG = texture2D(map, vMapUv).rgb;
        vec3 cD = texture2D(dirtMap, vMapUv).rgb;
        vec3 cS = texture2D(soilMap, uvS).rgb;
        vec3 albedo = mix(mix(cG, cD, wD), cS, wS);
        albedo *= mix(0.78, 1.18, clamp(macro * 2.0, 0.0, 1.0));
        diffuseColor.rgb *= albedo;`)
      .replace('vec4 texelRoughness = texture2D( roughnessMap, vRoughnessMapUv );', `
        vec4 texelRoughness = mix(mix(texture2D(roughnessMap, vRoughnessMapUv), texture2D(dirtRough, vRoughnessMapUv), wD),
                                  texture2D(soilRough, vRoughnessMapUv * soilScale), wS);`)
      .replace('vec3 mapN = texture2D( normalMap, vNormalMapUv ).xyz * 2.0 - 1.0;', `
        vec3 mapN = mix(mix(texture2D(normalMap, vNormalMapUv).xyz, texture2D(dirtNormal, vNormalMapUv).xyz, wD),
                        texture2D(soilNormal, vNormalMapUv * soilScale).xyz, wS) * 2.0 - 1.0;`);
  };
  return m;
}

// ---------------------------------------------------------------- terrain sampler (height + masks)
function makeTerrainSampler(mesh) {
  const N = mesh.userData.terrain_grid;
  const S = mesh.userData.terrain_size;
  const pos = mesh.geometry.attributes.position;
  const col = mesh.geometry.attributes.color;
  mesh.updateWorldMatrix(true, false);
  const h = new Float32Array((N + 1) * (N + 1));
  const m = new Float32Array((N + 1) * (N + 1) * 3);
  const v = new THREE.Vector3();
  for (let k = 0; k < pos.count; k++) {
    v.fromBufferAttribute(pos, k).applyMatrix4(mesh.matrixWorld);
    const i = Math.round((v.x + S / 2) / S * N);
    const j = Math.round((-v.z + S / 2) / S * N); // three -Z = Blender +Y
    if (i < 0 || j < 0 || i > N || j > N) continue;
    const idx = j * (N + 1) + i;
    h[idx] = v.y;
    m[idx * 3] = col.getX(k); m[idx * 3 + 1] = col.getY(k); m[idx * 3 + 2] = col.getZ(k);
  }
  function lerp(arr, x, z, stride = 1, c = 0) {
    const fx = THREE.MathUtils.clamp((x + S / 2) / S * N, 0, N - 1e-3);
    const fz = THREE.MathUtils.clamp((-z + S / 2) / S * N, 0, N - 1e-3);
    const i = Math.floor(fx), j = Math.floor(fz), tx = fx - i, tz = fz - j;
    const a = arr[(j * (N + 1) + i) * stride + c], b = arr[(j * (N + 1) + i + 1) * stride + c];
    const d = arr[((j + 1) * (N + 1) + i) * stride + c], e = arr[((j + 1) * (N + 1) + i + 1) * stride + c];
    return (a * (1 - tx) + b * tx) * (1 - tz) + (d * (1 - tx) + e * tx) * tz;
  }
  return {
    height: (x, z) => lerp(h, x, z),
    mask: (x, z) => [lerp(m, x, z, 3, 0), lerp(m, x, z, 3, 1), lerp(m, x, z, 3, 2)],
  };
}

// ---------------------------------------------------------------- instanced grass
function makeGrass(sampler) {
  const BLADES = 7, SEGS = 4;
  const pos = [], nrm = [], col = [], idx = [];
  const rnd = mulberry32(42);
  for (let b = 0; b < BLADES; b++) {
    const a = rnd() * Math.PI * 2, ox = (rnd() - 0.5) * 0.35, oz = (rnd() - 0.5) * 0.35;
    const H = 0.28 + rnd() * 0.42, W = 0.035 + rnd() * 0.02, bend = 0.12 + rnd() * 0.25;
    const ca = Math.cos(a), sa = Math.sin(a);
    const base = pos.length / 3;
    for (let s = 0; s <= SEGS; s++) {
      const t = s / SEGS, w = W * (1 - t * 0.92), y = H * t, f = bend * t * t;
      for (const side of [-1, 1]) {
        pos.push(ox + ca * side * w - sa * f, y, oz + sa * side * w + ca * f);
        nrm.push(0, 1, 0);
        const c = 0.45 + 0.55 * t;
        col.push(0.16 * c + 0.1 * t, 0.26 * c + 0.06 * t, 0.07 * c);
      }
    }
    for (let s = 0; s < SEGS; s++) {
      const q = base + s * 2;
      idx.push(q, q + 1, q + 3, q, q + 3, q + 2);
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geo.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
  geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  geo.setIndex(idx);
  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.85, side: THREE.DoubleSide });
  addWind(mat, 0.35, 2.0, true);

  const count = HIGH ? 110000 : 30000;
  const radius = HIGH ? 62 : 42;
  const center = new THREE.Vector2(-2, -6);
  const mesh = new THREE.InstancedMesh(geo, mat, count);
  const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), s = new THREE.Vector3(), p = new THREE.Vector3();
  const up = new THREE.Vector3(0, 1, 0), tint = new THREE.Color();
  let n = 0;
  for (let tries = 0; n < count && tries < count * 6; tries++) {
    const r = radius * Math.sqrt(rnd()), a = rnd() * Math.PI * 2;
    const x = center.x + r * Math.cos(a), z = center.y + r * Math.sin(a);
    const [dirt, soil, nog] = sampler.mask(x, z);
    if (nog > 0.4 || soil > 0.25 || dirt > 0.25 + rnd() * 0.35) continue;
    p.set(x, sampler.height(x, z) - 0.02, z);
    q.setFromAxisAngle(up, rnd() * Math.PI * 2);
    const edge = 1 - THREE.MathUtils.smoothstep(r, radius * 0.7, radius);
    if (rnd() > 0.25 + 0.75 * edge) continue;
    const sc = (0.7 + rnd() * 0.7 * (1 - dirt * 1.5)) * (0.45 + 0.55 * edge);
    s.set(sc, sc * (0.8 + rnd() * 0.5), sc);
    mesh.setMatrixAt(n, m4.compose(p, q, s));
    const dry = Math.max(0, rnd() - 0.75) * 2.2;
    tint.setRGB(0.85 + 0.35 * dry + rnd() * 0.15, 0.9 + 0.2 * dry + rnd() * 0.15, 0.7 + rnd() * 0.25);
    mesh.setColorAt(n, tint);
    n++;
  }
  mesh.count = n;
  mesh.receiveShadow = true;
  mesh.frustumCulled = false;
  return mesh;
}

function mulberry32(a) {
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// ---------------------------------------------------------------- load the farm
const loaderBar = document.getElementById('loaderBar');
const loaderText = document.getElementById('loaderText');
let rotor = null, waterMat = null, sampler = null;

const gltfLoader = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
gltfLoader.load('/farm/farm.glb', (gltf) => {
  const root = gltf.scene;
  const layers = {};
  const helpers = [];
  let terrain = null;
  root.traverse((o) => {
    if (o.name.startsWith('TexLayer_')) {
      helpers.push(o);
      layers[o.name.slice(9)] = o.material;
      return;
    }
    if (o.name === 'Windmill_Rotor') rotor = o;
    if (!o.isMesh) return;
    if (o.name === 'Terrain' || o.parent?.name === 'Terrain') terrain = o;
    o.castShadow = true;
    o.receiveShadow = true;
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    for (const mat of mats) tuneMaterial(mat);
  });
  helpers.forEach((h) => h.removeFromParent());
  if (terrain) {
    terrain.userData = { ...terrain.parent.userData, ...terrain.userData };
    terrain.material = terrainMaterial(layers);
    terrain.castShadow = false;
    sampler = makeTerrainSampler(terrain);
    scene.add(makeGrass(sampler));
  }
  scene.add(root);
  setSun(Number(document.getElementById('sun').value));
  const loader = document.getElementById('loader');
  if (STILL) loader.remove(); else loader.classList.add('done');
  window.__farmReady = true;
}, (e) => {
  if (e.total) loaderBar.style.width = `${(e.loaded / e.total) * 100}%`;
}, (err) => {
  console.error(err);
  loaderText.textContent = 'Could not load the farm model.';
});

function tuneMaterial(mat) {
  if (mat.userData.tuned) return;
  mat.userData.tuned = true;
  const name = mat.name;
  if (name === 'leaves' || name === 'corn_leaf') {
    mat.alphaTest = 0.45;
    mat.side = THREE.DoubleSide;
    mat.transparent = false;
    addWind(mat, name === 'leaves' ? 0.0035 : 0.022, name === 'leaves' ? 1.6 : 2.0, name === 'leaves');
  } else if (name === 'glass') {
    mat.envMapIntensity = 1.6;
  } else if (name === 'pond_water') {
    mat.color.setRGB(0.035, 0.07, 0.06);
    mat.roughness = 0.05;
    mat.metalness = 0.0;
    mat.envMapIntensity = 1.4;
    if (mat.normalMap) {
      mat.normalMap.wrapS = mat.normalMap.wrapT = THREE.RepeatWrapping;
      mat.normalScale.set(0.25, 0.25);
    }
    waterMat = mat;
  }
  const macro = { barn_wood: 0.22, siding: 0.12, roof_metal: 0.25, silo_metal: 0.18, shingles: 0.2, stone: 0.15,
    trim: 0.08, old_wood: 0.15, galv: 0.15, brick: 0.15, concrete: 0.15, straw: 0.15, bark: 0.1, rock: 0.2 }[name];
  if (macro) addMacro(mat, macro);
  for (const key of ['map', 'normalMap', 'roughnessMap']) {
    if (mat[key]) mat[key].anisotropy = renderer.capabilities.getMaxAnisotropy();
  }
}

// ---------------------------------------------------------------- UI + loop
document.getElementById('sun').addEventListener('input', (e) => setSun(Number(e.target.value)));
const spinBtn = document.getElementById('spin');
spinBtn.addEventListener('click', () => {
  controls.autoRotate = !controls.autoRotate;
  spinBtn.textContent = controls.autoRotate ? 'Stop rotating' : 'Auto-rotate';
});

addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  composer?.setSize(innerWidth, innerHeight);
});

const clock = new THREE.Clock();
let framesAfterLoad = 0;
renderer.setAnimationLoop(() => {
  if (STILL && window.__farmReady && ++framesAfterLoad > 3) {
    renderer.setAnimationLoop(null);
    window.__farmStill = true;
    return;
  }
  const dt = Math.min(clock.getDelta(), 0.1);
  wind.uTime.value += dt;
  if (rotor) rotor.rotateY(dt * 2.2);
  if (waterMat?.normalMap) waterMat.normalMap.offset.set(wind.uTime.value * 0.004, wind.uTime.value * 0.006);
  controls.update();
  if (sampler) { // keep the camera above the ground
    const minY = sampler.height(camera.position.x, camera.position.z) + 1.6;
    if (camera.position.y < minY) camera.position.y = minY;
  }
  sun.target.position.copy(controls.target).setY(0);
  sun.position.copy(sunDir).multiplyScalar(200).add(sun.target.position);
  if (composer) composer.render(); else renderer.render(scene, camera);
});
